--
-- Tabellenstruktur für Tabelle `Dim_Datum`
--

DROP TABLE IF EXISTS `Dim_Datum`;
CREATE TABLE `Dim_Datum` (
  `datum_id` bigint(20) NOT NULL,
  `datum` date NOT NULL,
  `jahr` int(11) NOT NULL,
  `quartal` int(11) NOT NULL,
  `monat` int(11) NOT NULL,
  `woche` int(11) NOT NULL,
  `tag` int(11) NOT NULL,
  `wochentag` varchar(10) NOT NULL,
  `stunde` int(11) NOT NULL,
  `minute` int(11) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Daten für Tabelle `Dim_Datum`
--


