--
-- Stellvertreter-Struktur des Views `Dim_Datum_Full`
-- (Siehe unten für die tatsächliche Ansicht)
--
DROP VIEW IF EXISTS `Dim_Datum_Full`;
CREATE TABLE `Dim_Datum_Full` (
`datum_id` bigint(20)
,`full_datetime` datetime /* mariadb-5.3 */
);

