INSERT INTO `Dim_Nachrichten` (`nachrichten_id`, `produkt_id`, `datum_id`, `titel`, `quelle`, `url`, `inhalt`) VALUES
(1, 5, 239, 'Asus ROG Strix OLED XG27UCDMG im Test: High-End Gaming-Display mit 27 Zoll, UHD und 240 Hz', 'ComputerBase', 'https://www.computerbase.de/artikel/monitore/asus-rog-strix-oled-xg27ucdmg-test.92011/', 'Mit dem ROG Strix OLED XG27UCDMG liefert Asus einen zweiten QD-OLED-Monitor der 4. Generation mit 26,5 Zoll, UHD und 240 Hz. Ohne DisplayPort 2.1 mit DP 1.4 und DSC ist er deutlich günstiger. Im Test überzeugt der Monitor auf ganzer Linie und ist nicht nur fü…'),
(2, 5, 240, 'Die besten Windows-Notebooks mit 14-Zoll-Display im Vergleich: Das sind gute MacBook Air-Alternativen', 'netzwelt', 'https://www.netzwelt.de/vergleich/kompakte-ki-rechner-test-besten-windows-notebooks-14-zoll-display.html', 'Hat euer Notebook noch keine KI-Funktionen und läuft etwa noch mit Windows 10? Dann ist jetzt die Zeit für eine Neuanschaffung gekommen. Wir haben 5 aktuelle 14-Zoll-Laptops getestet und einen Testsieger gekürt.'),
(3, 5, 241, 'Die besten Windows-Notebooks mit 14-Zoll-Display im Vergleich: Das sind gute MacBook Air-Alternativen', 'netzwelt', 'https://www.netzwelt.de/vergleich/kompakte-ki-rechner-test-besten-windows-11-notebooks-14-zoll-display.html', 'Hat euer Notebook noch keine KI-Funktionen und läuft etwa noch mit Windows 10? Dann ist jetzt die Zeit für eine Neuanschaffung gekommen. Wir haben 5 aktuelle 14-Zoll-Laptops getestet und einen Testsieger gekürt.'),
(4, 6, 242, 'Die besten Windows-Notebooks mit 14-Zoll-Display im Vergleich: Das sind gute MacBook Air-Alternativen', 'netzwelt', 'https://www.netzwelt.de/vergleich/kompakte-ki-rechner-test-besten-windows-notebooks-14-zoll-display.html', 'Hat euer Notebook noch keine KI-Funktionen und läuft etwa noch mit Windows 10? Dann ist jetzt die Zeit für eine Neuanschaffung gekommen. Wir haben 5 aktuelle 14-Zoll-Laptops getestet und einen Testsieger gekürt.'),
(5, 6, 243, 'Die besten Windows-Notebooks mit 14-Zoll-Display im Vergleich: Das sind gute MacBook Air-Alternativen', 'netzwelt', 'https://www.netzwelt.de/vergleich/kompakte-ki-rechner-test-besten-windows-11-notebooks-14-zoll-display.html', 'Hat euer Notebook noch keine KI-Funktionen und läuft etwa noch mit Windows 10? Dann ist jetzt die Zeit für eine Neuanschaffung gekommen. Wir haben 5 aktuelle 14-Zoll-Laptops getestet und einen Testsieger gekürt.'),
(6, 6, 244, 'Dell 14 Plus im Test: Noch Brot und Butter oder schon Premium?', 'netzwelt', 'https://www.netzwelt.de/dell-14-plus-2025/testbericht.html', 'Mit kräftigen Intel-Prozessoren und einer Portion Understatement tritt das neue Dell 14 Plus zum Test an. Ist es wirklich eine Art Universalgenie? Das eine Notebook für alles?\nDieser Artikel wurde einsortiert unter \nKaufberatung,Notebook,Dell,Technology,Mobil…'),
(7, 6, 245, 'Asus Zenbook 14 Duo OLED: Test des Laptops mit Doppel-Display', 'COMPUTER BILD', 'https://www.computerbild.de/artikel/Asus-Zenbook-14-Duo-OLED-Test-Review-39585091.html', 'Sie wollen unterwegs mehr Bildschirmfläche? Dann ist der 14-Zoll-Laptop Asus Zenbook 14 Duo OLED eine echte Alternative zu größeren 16- und 17-Zoll-Modellen.'),
(8, 6, 246, 'Lenovo ThinkPad X9-14 Gen 1 im Test: Darf es heute ein wenig mehr sein?', 'netzwelt', 'https://www.netzwelt.de/lenovo-thinkpad-x9-14-gen-1/testbericht.html', 'Sieht gar nicht aus wie ein typisches Lenovo ThinkPad, entpuppt sich im Test aber als famoser Windows-Laptop für alle Gelegenheiten. Darf es heute ein wenig mehr sein?\nDieser Artikel wurde einsortiert unter \nKaufberatung,Notebook,Lenovo,Technology,Mobile Comp…'),
(9, 4, 247, 'Mehrere Probleme in Linux (SUSE)', 'Pro-Linux', 'https://www.pro-linux.de/sicherheit/2/89014/sicherheit-mehrere-probleme-in-linux.html', 'Kostenlose Nachrichten, Web-Support und Foren rund um Linux, OpenSource und Freie Software. Angebote wie News, Berichte, Workshops, Tipps, Links und Kalender.'),
(10, 4, 248, 'Mehrere Probleme in Linux (SUSE)', 'Pro-Linux', 'https://www.pro-linux.de/sicherheit/2/89010/sicherheit-mehrere-probleme-in-linux.html', 'Kostenlose Nachrichten, Web-Support und Foren rund um Linux, OpenSource und Freie Software. Angebote wie News, Berichte, Workshops, Tipps, Links und Kalender.'),
(11, 4, 249, 'Mehrere Probleme in Linux (SUSE)', 'Pro-Linux', 'https://www.pro-linux.de/sicherheit/2/88999/sicherheit-mehrere-probleme-in-linux.html', 'Kostenlose Nachrichten, Web-Support und Foren rund um Linux, OpenSource und Freie Software. Angebote wie News, Berichte, Workshops, Tipps, Links und Kalender.'),
(12, 8, 250, 'Ultradünne Laptops: LG stellt die 2025er-Modelle der »gram Pro«-Reihe vor', 'GameStar', 'https://www.gamestar.de/videos/ultraduenne-laptops-lg-stellt-die-2025er-modelle-der-gram-pro-reihe-vor,135571.html', 'Mit einem Trailer hat LG neue Laptops aus der&nbsp;&raquo;gram Pro&laquo;-Reihe vorgestellt. Bei den 2025er-Modellen steht wenig &uuml;berraschend KI im Fokus.\n\nDie&nbsp;&raquo;gram Pro&laquo;-Reihe zeichnet sich durch ein besonders schlankes und leichtes Des…'),
(13, 8, 251, 'LG Gram 15: Leichtes Notebook setzt erstmals auf AMD Ryzen AI', 'ComputerBase', 'https://www.computerbase.de/news/notebooks/lg-gram-15-leichtes-notebook-setzt-erstmals-auf-amd-ryzen-ai.92120/', 'LGs Gram-Serie gibt es schon seit 2022, bisher allerdings exklusiv mit Prozessoren von Intel. Dies wird sich in Kürze ändern, da LG in Korea nun das erste Modell mit Ryzen-AI-CPU verfügbar machen will. Das „Gram 15“ soll auf vor allem mit KI-Funktionen punkte…'),
(14, 1, 252, 'Die besten Windows-Notebooks mit 14-Zoll-Display im Vergleich: Das sind gute MacBook Air-Alternativen', 'netzwelt', 'https://www.netzwelt.de/vergleich/kompakte-ki-rechner-test-besten-windows-notebooks-14-zoll-display.html', 'Hat euer Notebook noch keine KI-Funktionen und läuft etwa noch mit Windows 10? Dann ist jetzt die Zeit für eine Neuanschaffung gekommen. Wir haben 5 aktuelle 14-Zoll-Laptops getestet und einen Testsieger gekürt.'),
(15, 1, 253, 'Die besten Windows-Notebooks mit 14-Zoll-Display im Vergleich: Das sind gute MacBook Air-Alternativen', 'netzwelt', 'https://www.netzwelt.de/vergleich/kompakte-ki-rechner-test-besten-windows-11-notebooks-14-zoll-display.html', 'Hat euer Notebook noch keine KI-Funktionen und läuft etwa noch mit Windows 10? Dann ist jetzt die Zeit für eine Neuanschaffung gekommen. Wir haben 5 aktuelle 14-Zoll-Laptops getestet und einen Testsieger gekürt.'),
(16, 1, 254, 'Kunden-Backup landet bei fremder Person', 'heise online', 'https://www.heise.de/ratgeber/Kunden-Backup-landet-bei-fremder-Person-9809790.html', 'Durch einen Fehler landet das Backup einer Kundin auf dem falschen Rechner. Ein schwerwiegender Datenschutzverstoß. Die Betroffene wartet lange auf Erklärungen.'),
(17, 1, 255, 'Apcuwcq USB C auf DisplayPort Kabel 2M 8K@60Hz 30Hz 4K@240Hz 144Hz HDR VRR Thunderbolt 4 3 DP1.4 Kabel kompatibel mit iPhone 15 MacBook Pro Air M1 M2 iPad Pro Air 5 Surface Pro 8 Galaxy S23 S22', 'Amazon.de', 'https://www.amazon.de/-/en/APCUWCQ-DisplayPort-Thunderbolt-Compatible-MacBook/dp/B0CRCVQ4V9', 'Sonntag ab 08:15 Uhr: Apcuwcq USB C auf DisplayPort Kabel 2M 8K@60Hz 30Hz 4K@240Hz 144Hz HDR VRR Thunderbolt 4 3 DP1.4 Kabel kompatibel mit iPhone 15 MacBook Pro Air M1 M2 iPad Pro Air 5 Surface Pro 8 Galaxy S23 S22 für nur 5,94 Euro\r\n (regulärer Amazon Preis…'),
(18, 1, 256, 'Apple Intelligence: Verfügbarkeit auf Geräten und Funktionen erklärt', 'Giga', 'https://www.giga.de/tech/apple-intelligence-verfuegbarkeit-auf-geraeten-und-funktionen-erklaert--01J5QXXAXAYFH61TVWZTFNVYMG', 'Die Betriebssysteme iOS 18.4 und iPadOS 18.4 wurden veröffentlicht und damit die angekündigten KI-Funktionen von „Apple Intelligence“. Welche Geräte das Feature bekommen und welche Funktionen euch dann zur Verfügung stehen, erklären wir euch nachfolgend.'),
(19, 7, 257, 'Für unter 500 Euro: Hochwertiger Microsoft-Laptop stark vergünstigt bei Amazon', 'Giga', 'https://www.giga.de/tech/fuer-unter-500-euro-hochwertiger-microsoft-laptop-stark-verguenstigt-bei-amazon--01JQEKPGB9H9ZK26CZEG1D1WY5', 'Bei Amazon bekommt ihr momentan den Laptop Microsoft Surface Go 3 zum stark vergünstigten Preis. Wir haben uns das Angebot angesehen und die Details für euch.'),
(20, 7, 258, 'Für unter 500 Euro: Amazon verkauft hochwertigen Microsoft-Laptop zum Rekordpreis', 'Kino.de', 'https://www.kino.de/film/angebote-und-deals/news/fuer-unter-500-euro-amazon-verkauft-hochwertigen-microsoft-laptop-zum-rekordpreis/', 'Im Rahmen der Amazon-Frühlingsangebote bekommt ihr den Microsoft-Laptop Surface Go 3 zum historischen Tiefpreis...'),
(21, 7, 259, 'Kopfhörer, Airfryer, Staubsauger und Co. - Diese Technik-Testsieger sind jetzt günstiger', 'Bild', 'https://www.bild.de/leben-wissen/digital/elektronik-haushalt-freizeit-diese-testsieger-sind-jetzt-stark-reduziert-67e66c41032de159434d0e5c', 'Finden Sie heraus, welche hochwertigen Produkte von COMPUTER BILD Experten getestet wurden und heute zum besten Preis erhältlich sind. Sichern Sie sich die besten Schnäppchen!'),
(22, 7, 260, 'Für unter 500 Euro: Hochwertiger Microsoft-Laptop historisch günstig bei Amazon', 'Giga', 'https://www.giga.de/tech/fuer-unter-500-euro-hochwertiger-microsoft-laptop-historisch-guenstig-bei-amazon--01JQEKPGB9H9ZK26CZEG1D1WY5', 'Bei Amazon bekommt ihr im Rahmen der Frühlingsangebote den Laptop Microsoft Surface Go 3 zum historisch günstigen Preis. Wir haben uns das Angebot angesehen und die Details für euch.'),
(23, 7, 261, ' WOW! Microsoft Surface Laptop Go 3 mit 12,45 Zoll für 479€ (statt 736€)', 'Mein-deal.com', 'https://www.mein-deal.com/wow-microsoft-surface-laptop-go-3/', 'Die Surface Laptops sind schon nicht ganz billig. Und der vorherige Preis von über 700€ war wohl auch etwas übertrieben. Aber Amazon gönnt uns hier'),
(24, 9, 262, 'Test: Razer Blade 16 im Test - Das neue Notebook sprengt meine Erwartungen', 'GameStar', 'https://www.gamestar.de/artikel/razer-blade-16-2025-review,3429931.html', 'Das neueste Razer Blade 16 Modell mit RTX-5090-GPU setzt Maßstäbe für Leistung und Design im Gaming-Laptop-Segment.'),
(25, 9, 263, 'GeForce RTX 5090 Laptop GPU im Test: Nvidias neues Flaggschiff im bisher dünnsten Razer Blade', 'ComputerBase', 'https://www.computerbase.de/artikel/grafikkarten/razer-blade-16-geforce-rtx-5090-laptop-gpu-test.91790/', 'Nach vier Auftritten im Desktop-PCs ist Nvidia Blackwell im Notebook angekommen. Der Test analysiert Leistung und Features des neuen Topmodells GeForce RTX 5090 Laptop GPU 24 GB im neuen, noch dünneren Razer Blade 16 (2025). So schnell ist die neue GPU im Ver…'),
(26, 9, 264, 'Linux-News der Woche: AMD bringt Vulkan-Treiber für RX 9070 (XT), DXVK 2.6', 'ComputerBase', 'https://www.computerbase.de/news/betriebssysteme/linux-news-der-woche-amd-bringt-vulkan-treiber-fuer-rx-9070-xt-dxvk-2-6.91800/', 'AMD hatte zum RDNA 4 Release noch keinen eigenen Vulkan-Treiber im Angebot, somit blieb bislang nur der freie RADV-Treiber. Mit amdvlk 2025.Q1.3 holt AMD das Ganze nach. Mit DXVK 2.6 zieht Nvidia Reflex für ältere DirectX-11-Titel für Linux ein. Die SteamOS-V…');
